// src/pages/AudienceGate.jsx
import React, { useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { setAudience } from '../utils/audience';

export default function AudienceGate() {
  const nav = useNavigate();
  const loc = useLocation();
  const rootRef = useRef(null);
  const [chosen, setChosen] = useState(false);

  const trackMouse = (e) => {
    // mueve el brillo del hover
    const el = e.currentTarget;
    const r = el.getBoundingClientRect();
    el.style.setProperty('--mx', `${e.clientX - r.left}px`);
    el.style.setProperty('--my', `${e.clientY - r.top}px`);
  };

  const choose = (value) => {
    // marca animación
    setChosen(true);

    // persiste cookie + header axios
    setAudience(value);
    axios.defaults.headers.common['X-Audience'] = value;

    // esperar a que la animación del logo se vea (~340ms) y navegar
    const to =
      loc.state && loc.state.from
        ? loc.state.from.pathname + (loc.state.from.search || '')
        : '/';
    setTimeout(() => nav(to, { replace: true }), 360);
  };

  return (
    <div className={`ag-root ${chosen ? 'chosen' : ''}`} ref={rootRef}>
      <div className="ag-logo-wrap">
        <img src="/logo.png" alt="Conecta Pinamar" className="ag-logo" />
        <div className="ag-logo-underline" />
      </div>

      <div className="ag-split">
        <button
          className="ag-side left"
          onMouseMove={trackMouse}
          onClick={() => choose('TOURIST')}
          aria-label="Soy Turista"
        >
          <span className="ag-label">Soy Turista</span>
        </button>

        <button
          className="ag-side right"
          onMouseMove={trackMouse}
          onClick={() => choose('RESIDENT')}
          aria-label="Soy Residente"
        >
          <span className="ag-label">Soy Residente</span>
        </button>
      </div>
    </div>
  );
}
